<?php
$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'course';
 if($action==='subject'){$cid=(int)($_POST['course_id']??0);$name=trim($_POST['subject_name']??'');if($cid&&$name!==''){$pdo->prepare('INSERT INTO subjects(course_id,name,description) VALUES(?,?,?)')->execute([$cid,$name,trim($_POST['subject_description']??'')]);flash('Subject added.');}}
 else {$title=trim($_POST['title']??'');if($title!==''){$pdo->prepare('INSERT INTO courses(title,description,category) VALUES(?,?,?)')->execute([$title,trim($_POST['description']??''),trim($_POST['category']??'General')]);flash('Course created.');}}
 redirect('index.php?page=courses');}
$rows=$pdo->query("SELECT c.*,COUNT(DISTINCT s.id) subject_count FROM courses c LEFT JOIN subjects s ON s.course_id=c.id GROUP BY c.id ORDER BY c.created_at DESC")->fetchAll();
$subjects=$pdo->query('SELECT s.*,c.title course_title FROM subjects s JOIN courses c ON c.id=s.course_id ORDER BY c.title,s.name')->fetchAll();
?>
<div class="page-heading"><div><p class="eyebrow">MY LEARNING</p><h1>My Courses & Subjects</h1><p class="muted">Create learning collections and organize subjects.</p></div></div>
<div class="two-col">
<section class="card"><h2>Create a course</h2><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="course"><label>Course title</label><input name="title" required placeholder="e.g. Agriculture Officer Preparation"><label>Category</label><input name="category" placeholder="Academic, Professional, Personal"><label>Description</label><textarea name="description" rows="3"></textarea><button class="btn primary">＋ Add course</button></form>
<hr><h2>Add a subject</h2><?php if(!$rows):?><p class="muted">Create a course before adding subjects.</p><?php else:?><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="subject"><label>Course</label><select name="course_id"><?php foreach($rows as $c):?><option value="<?=$c['id']?>"><?=e($c['title'])?></option><?php endforeach;?></select><label>Subject name</label><input name="subject_name" required placeholder="e.g. Agronomy"><label>Description</label><textarea name="subject_description"></textarea><button class="btn secondary">Add subject</button></form><?php endif;?></section>
<section class="card"><h2>Your courses</h2><?php if(!$rows):?><div class="empty-state compact">Create your first learning collection.</div><?php else:foreach($rows as $r):?><div class="list-item"><div class="list-icon">▤</div><div class="grow"><b><?=e($r['title'])?></b><small><?=e($r['category'])?> · <?=$r['subject_count']?> subjects</small><small><?=e($r['description'])?></small></div></div><?php endforeach;endif;?>
<hr><h2>Subjects</h2><?php if(!$subjects):?><p class="muted">Subjects will appear here.</p><?php else:foreach($subjects as $s):?><div class="list-item"><div class="grow"><b><?=e($s['name'])?></b><small><?=e($s['course_title'])?></small></div></div><?php endforeach;endif;?></section></div>
